-- PT118-S4-Q1. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT118-S4-Q1$batch10$ AND q.stimulus=$batch10$Mayor McKinney’s policies have often been criticized on the grounds that they benefit only wealthy city residents, but that is not a fair evaluation. Some of McKinney’s policies have clearly benefited the city’s less affluent residents. McKinney actively supported last year’s proposal to lower the city’s high property taxes. Because of this tax decrease, more development is taking place in the city, helping to end the housing shortage and stabilize the rents in the city.$batch10$ AND q.prompt=$batch10$Which one of the following most accurately expresses the main conclusion of the argument?$batch10$ AND q.correct_choice=$batch10$D$batch10$) THEN RAISE EXCEPTION 'Question changed: PT118-S4-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT118-S4-Q1$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S4-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT118-S4-Q1$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Opposing Point$batch10$, $batch10$McKinney's policies have often been criticized as benefiting only wealthy residents.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$That criticism is not a fair evaluation.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$Some of McKinney's policies clearly benefited less affluent residents. McKinney supported lowering property taxes, which spurred development, easing the housing shortage and stabilizing rents.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$The first sentence pivots with "but that is not a fair evaluation," and that is the conclusion. Everything after it is support, with the tax example backing the claim that some policies helped poorer residents.$batch10$), (4, $batch10$Goal$batch10$, $batch10$The criticism that McKinney's policies benefit only the wealthy is unfair.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT118-S4-Q1$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$The argument does reach a judgment. It says the criticism is unfair.$batch10$), ($batch10$B$batch10$, $batch10$This is the criticism the argument rejects.$batch10$), ($batch10$C$batch10$, $batch10$This is part of the tax example used as support.$batch10$), ($batch10$D$batch10$, $batch10$The first sentence says the criticism is not fair. "Unjustified" means the same.$batch10$), ($batch10$E$batch10$, $batch10$This is the last link in the evidence chain. It supports the claim that poorer residents benefited.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT118-S4-Q1$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
